## Type Narrowing (сужение типа)

**Type narrowing** — механизм, при котором TypeScript сужает тип переменной после проверки.

**Способы narrowing:**

**1. typeof:**
```typescript
function process(value: string | number) {
  if (typeof value === "string") {
    // value: string
    console.log(value.toUpperCase())
  } else {
    // value: number
    console.log(value.toFixed(2))
  }
}
```

**2. instanceof:**
```typescript
function handleError(error: Error | string) {
  if (error instanceof Error) {
    // error: Error
    console.error(error.message)
  } else {
    // error: string
    console.error(error)
  }
}
```

**3. in:**
```typescript
type Fish = { swim: () => void }
type Bird = { fly: () => void }

function move(animal: Fish | Bird) {
  if ("swim" in animal) {
    // animal: Fish
    animal.swim()
  } else {
    // animal: Bird
    animal.fly()
  }
}
```

**4. Discriminated unions:**
```typescript
type Result =
  | { status: "success"; data: string }
  | { status: "error"; message: string }

function handle(result: Result) {
  if (result.status === "success") {
    // result: { status: "success"; data: string }
    console.log(result.data)
  } else {
    // result: { status: "error"; message: string }
    console.error(result.message)
  }
}
```

**5. Проверка на null/undefined:**
```typescript
function process(value: string | null | undefined) {
  if (value === null || value === undefined) {
    return "No value"
  }
  // value: string
  return value.toUpperCase()
}
```

**6. Array.isArray:**
```typescript
function process(value: string | string[]) {
  if (Array.isArray(value)) {
    // value: string[]
    console.log(value.join(", "))
  } else {
    // value: string
    console.log(value)
  }
}
```

**7. Пользовательские type guards:**
```typescript
function isString(value: unknown): value is string {
  return typeof value === "string"
}

function isUser(value: unknown): value is User {
  return (
    typeof value === "object" &&
    value !== null &&
    "name" in value &&
    "age" in value
  )
}

function process(value: unknown) {
  if (isString(value)) {
    // value: string
    console.log(value.toUpperCase())
  } else if (isUser(value)) {
    // value: User
    console.log(value.name)
  }
}
```

**8. Assertion functions:**
```typescript
function assertIsString(value: unknown): asserts value is string {
  if (typeof value !== "string") {
    throw new Error("Not a string")
  }
}

function process(value: unknown) {
  assertIsString(value)
  // value: string (после assertion)
  console.log(value.toUpperCase())
}
```

