## Discriminated Unions

**Discriminated unions** (tagged unions, algebraic data types) — union типы с общим свойством (discriminant), которое позволяет TypeScript сужать тип.

**Базовый пример:**
```typescript
type Success = {
  status: "success"  // discriminant
  data: string
}

type Error = {
  status: "error"    // discriminant
  message: string
}

type Result = Success | Error

function handle(result: Result) {
  if (result.status === "success") {
    // result: Success
    console.log(result.data)    // ✅
    // console.log(result.message)  // ❌ Ошибка
  } else {
    // result: Error
    console.error(result.message)  // ✅
    // console.log(result.data)     // ❌ Ошибка
  }
}
```

**Правила discriminated unions:**
1. Общий тип должен быть **литеральным типом** (строка, число, boolean, enum)
2. Общий тип должен быть **уникальным** для каждого члена union
3. TypeScript использует это свойство для narrowing

**Практические примеры:**

**1. API responses:**
```typescript
type ApiResponse<T> =
  | { status: 200; data: T }
  | { status: 404; error: "Not found" }
  | { status: 500; error: "Internal server error" }

function handleResponse<T>(response: ApiResponse<T>) {
  switch (response.status) {
    case 200:
      console.log(response.data)    // T
      break
    case 404:
      console.error(response.error) // "Not found"
      break
    case 500:
      console.error(response.error) // "Internal server error"
      break
  }
}
```

**2. State machines:**
```typescript
type LoadingState = {
  status: "loading"
}

type SuccessState<T> = {
  status: "success"
  data: T
}

type ErrorState = {
  status: "error"
  error: Error
}

type AsyncState<T> = LoadingState | SuccessState<T> | ErrorState

function render<T>(state: AsyncState<T>) {
  switch (state.status) {
    case "loading":
      return <Spinner />
    case "success":
      return <DataView data={state.data} />
    case "error":
      return <ErrorMessage error={state.error} />
  }
}
```

**3. Actions (Redux-like):**
```typescript
type Action =
  | { type: "INCREMENT" }
  | { type: "DECREMENT" }
  | { type: "SET_VALUE"; payload: number }
  | { type: "RESET" }

function reducer(state: number, action: Action): number {
  switch (action.type) {
    case "INCREMENT":
      return state + 1
    case "DECREMENT":
      return state - 1
    case "SET_VALUE":
      return action.payload  // ✅ payload доступен
    case "RESET":
      return 0
  }
}
```

**4. Form validation:**
```typescript
type ValidationSuccess = {
  valid: true
  value: string
}

type ValidationError = {
  valid: false
  errors: string[]
}

type ValidationResult = ValidationSuccess | ValidationError

function validate(input: string): ValidationResult {
  if (input.length < 3) {
    return { valid: false, errors: ["Too short"] }
  }
  return { valid: true, value: input }
}

const result = validate("Hi")
if (result.valid) {
  console.log(result.value)  // ✅
} else {
  console.error(result.errors)  // ✅
}
```

**5. Pattern matching:**
```typescript
type Option<T> =
  | { type: "some"; value: T }
  | { type: "none" }

function match<T, R>(
  option: Option<T>,
  handlers: {
    some: (value: T) => R
    none: () => R
  }
): R {
  switch (option.type) {
    case "some":
      return handlers.some(option.value)
    case "none":
      return handlers.none()
  }
}

const result = match(
  { type: "some", value: 42 },
  {
    some: (value) => value * 2,
    none: () => 0
  }
)
// result: 84
```

